use aap::caps::inference_llm::infer;
use aap::caps::types::{Category, ClassifiedItem, Classification, DroppedItem, Importance};

struct Node;

impl Guest for Node {
    fn run(item: FeedItem) -> Classification {
        let system = "You are a feed item classifier. Given a title and text, \
            respond with exactly one category (release, security, research, \
            tooling, discussion, other) and exactly one importance \
            (must-read, worth-a-look, skip), separated by a comma, e.g. \
            'security,must-read'. Respond with nothing else.";

        let prompt = format!(
            "Title: {}\nText: {}",
            item.title, item.text
        );

        let response = infer(system, &prompt, "classify");

        let (category, importance) = parse_response(&response);

        match importance {
            Importance::Skip => Classification::Drop(DroppedItem { item, category }),
            _ => Classification::Keep(ClassifiedItem {
                item,
                category,
                importance,
            }),
        }
    }
}

fn parse_response(response: &str) -> (Category, Importance) {
    let mut parts = response.splitn(2, ',');
    let cat_str = parts.next().unwrap_or("").trim().to_lowercase();
    let imp_str = parts.next().unwrap_or("").trim().to_lowercase();

    let category = match cat_str.as_str() {
        "release" => Category::Release,
        "security" => Category::Security,
        "research" => Category::Research,
        "tooling" => Category::Tooling,
        "discussion" => Category::Discussion,
        _ => Category::Other,
    };

    let importance = match imp_str.as_str() {
        "must-read" => Importance::MustRead,
        "worth-a-look" => Importance::WorthALook,
        _ => Importance::Skip,
    };

    (category, importance)
}

export!(Node);
